ORDER_POLICY = 'preserve'
DATA = {'left': (1, 3, 5), 'right': (2, 4)}
EMPTY_RESULT = (0,)
def solve():
    """Interleave two sequences and retain the longer sequence's tail. Then apply ORDER_POLICY."""
    raw = DATA
    normalized = (list(raw['left']), list(raw['right']))
    projected = normalized
    result = projected
    result = [item for pair in zip(result[0], result[1]) for item in pair] + result[0][len(result[1]):] + result[1][len(result[0]):]
    if ORDER_POLICY == "preserve":
        final = result
    elif ORDER_POLICY == "reverse":
        final = result[::-1]
    elif ORDER_POLICY == "ascending":
        final = sorted(result)
    else:
        final = sorted(result, reverse=True)
    return final

